func init() {
	certificateListCmd.Flags().StringP("target", "T", "_all", "Target: _all, _any, hostname, or label (group:web.dev)")
	certificateGetCmd.Flags().StringP("target", "T", "_all", "Target: _all, _any, hostname, or label (group:web.dev)")
	certificateGetCmd.Flags().String("name", "", "The CA, as list names it, such as internal-ca, or ISRG Root X1 on macOS; a name with a slash, such as mozilla/ISRG_Root_X1, is in list only, because a path segment cannot have one")
	_ = certificateGetCmd.MarkFlagRequired("name")
	certificateCreateCmd.Flags().StringP("target", "T", "_all", "Target: _all, _any, hostname, or label (group:web.dev)")
	certificateCreateCmd.Flags().String("name", "", "The name of the CA, such as internal-ca, which osapi writes as osapi-internal-ca.crt")
	_ = certificateCreateCmd.MarkFlagRequired("name")
	certificateCreateCmd.Flags().String("object", "", "The object of the Object Store that has the PEM of the CA, as osapi client file upload stored it")
	_ = certificateCreateCmd.MarkFlagRequired("object")
	certificateUpdateCmd.Flags().StringP("target", "T", "_all", "Target: _all, _any, hostname, or label (group:web.dev)")
	certificateUpdateCmd.Flags().String("name", "", "The CA that osapi deployed, such as internal-ca")
	_ = certificateUpdateCmd.MarkFlagRequired("name")
	certificateUpdateCmd.Flags().String("object", "", "The object that has the PEM; the one it was deployed from when empty")
	certificateDeleteCmd.Flags().StringP("target", "T", "_all", "Target: _all, _any, hostname, or label (group:web.dev)")
	certificateDeleteCmd.Flags().String("name", "", "The CA that osapi deployed, such as internal-ca")
	_ = certificateDeleteCmd.MarkFlagRequired("name")
	clicommand.AddCommands(Group, certificateListCmd, certificateGetCmd, certificateCreateCmd, certificateUpdateCmd, certificateDeleteCmd)
}
